const calculateAveragePendingAge=(rows,now=new Date())=>{const values=rows.filter(f=>f.status!=='CLOSED'&&f.created_at).map(f=>Math.max(0,(now-new Date(f.created_at))/DAY_MS));return values.length?values.reduce((a,b)=>a+b,0)/values.length:null};
const calculateResolutionSpeedScore=days=>days===null?0:days<=2?100:days<=3?90:days<=5?75:days<=7?60:days<=14?40:20;
function getPerformanceClassification(score,total){if(!total)return'NO FINDINGS';if(total<PERFORMANCE_MIN_FINDINGS)return'INSUFFICIENT DATA';return score>=90?'EXCELLENT':score>=80?'VERY GOOD':score>=70?'GOOD':score>=60?'NEEDS ATTENTION':'CRITICAL'}
function calculateStorePerformance(store,rows,now=new Date()){const total=rows.length,resolved=rows.filter(f=>f.status==='CLOSED').length,pending=total-resolved,overdueCount=rows.filter(f=>f.status!=='CLOSED'&&f.due_date&&new Date(f.due_date+'T23:59:59')<now).length,verification=rows.filter(f=>f.status==='FOR_VERIFICATION').length,critical=rows.filter(f=>f.status!=='CLOSED'&&f.priority==='CRITICAL').length,resolutionRate=calculateResolutionRate(resolved,total),avgResolution=calculateAverageResolutionDays(rows),avgPendingAge=calculateAveragePendingAge(rows,now),speedScore=calculateResolutionSpeedScore(avgResolution),pendingControl=total?100-pending/total*100:0,overdueControl=total?100-overdueCount/total*100:0,score=total?Math.round(resolutionRate*.5+speedScore*.25+pendingControl*.15+overdueControl*.1):null;return{...store,total,resolved,pending,overdue:overdueCount,verification,critical,resolutionRate,avgResolution,avgPendingAge,speedScore,pendingControl,overdueControl,score,eligible:total>=PERFORMANCE_MIN_FINDINGS,classification:getPerformanceClassification(score,total),findings:rows}}
function reportingBounds(period,start,end,now=new Date()){let from=null,to=new Date(now);to.setHours(23,59,59,999);if(period==='THIS_MONTH')from=new Date(now.getFullYear(),now.getMonth(),1);if(period==='LAST_MONTH'){from=new Date(now.getFullYear(),now.getMonth()-1,1);to=new Date(now.getFullYear(),now.getMonth(),0,23,59,59,999)}if(period==='LAST_30')from=new Date(now.getTime()-29*DAY_MS);if(period==='LAST_90')from=new Date(now.getTime()-89*DAY_MS);if(period==='YTD')from=new Date(now.getFullYear(),0,1);if(period==='CUSTOM'){from=start?new Date(start+'T00:00:00'):null;to=end?new Date(end+'T23:59:59'):to}return{from,to}}

function Badge({type,value}){return <span className={'badge '+type+' '+String(value).toLowerCase()}>{type==='status'?statusName(value):value}</span>}
function PerformanceBadge({item}){return <span className={'performanceBadge '+item.classification.toLowerCase().replaceAll(' ','-')}>{item.classification}</span>}
function StorePerformanceDetails({item,cats,onClose}){const priority={CRITICAL:4,HIGH:3,MEDIUM:2,LOW:1},pending=item.findings.filter(f=>f.status!=='CLOSED').sort((a,b)=>(overdue(b)?1:0)-(overdue(a)?1:0)||(priority[b.priority]||0)-(priority[a.priority]||0)||new Date(a.created_at)-new Date(b.created_at)),parts=[['Resolution Rate',item.resolutionRate??0,'50%'],['Resolution Speed',item.speedScore,'25%'],['Pending Control',item.pendingControl,'15%'],['Overdue Control',item.overdueControl,'10%']];return <div className="perfModal" role="dialog" aria-modal="true" aria-label={item.store_name+' performance'}><div className="perfDialog"><header><div><span className="eyebrow">{item.store_code} · {item.area}</span><h2>{item.store_name}</h2><p>Store Performance</p></div><button className="iconBtn" onClick={onClose} aria-label="Close"><X/></button></header><div className="perfDetailStats"><Stat label="Performance Score" value={item.score===null?'—':item.score}/><Stat label="Total Findings" value={item.total}/><Stat label="Resolved" value={item.resolved} tone="green"/><Stat label="Pending" value={item.pending} tone="gold"/><Stat label="Overdue" value={item.overdue} tone="orange"/><Stat label="Resolution Rate" value={item.resolutionRate===null?'N/A':Math.round(item.resolutionRate)+'%'} tone="blue"/><Stat label="Avg. Resolution" value={item.avgResolution===null?'—':item.avgResolution.toFixed(1)+' days'}/><Stat label="Avg. Pending Age" value={item.avgPendingAge===null?'—':item.avgPendingAge.toFixed(1)+' days'}/></div><section className="scoreBreakdown"><div className="sectionHead"><div><span className="eyebrow">Transparent scoring</span><h3>Performance Score Breakdown</h3></div><PerformanceBadge item={item}/></div>{parts.map(([label,value,weight])=><div className="scorePart" key={label}><span>{label}<small>Weight: {weight}</small></span><i><b style={{width:Math.max(0,Math.min(100,value))+'%'}}></b></i><strong>{Math.round(value)} / 100</strong></div>)}<div className="finalScore"><span>Final Score</span><strong>{item.score===null?'—':item.score+' / 100'}</strong></div></section><section className="pendingDetail"><h3>Pending Findings</h3>{pending.length?<div className="perfTableWrap"><table className="perfTable compact"><thead><tr><th>Finding</th><th>Category</th><th>Priority</th><th>Status</th><th>Age</th><th>Due Date</th></tr></thead><tbody>{pending.map(f=><tr key={f.id}><td><strong>{f.title}</strong><small>{f.finding_no}</small></td><td>{cats.find(c=>c.id===f.category_id)?.name||'—'}</td><td><Badge type="priority" value={f.priority}/></td><td><Badge type="status" value={f.status}/>{overdue(f)&&<span className="badge overdue">OVERDUE</span>}</td><td>{Math.floor(Math.max(0,(new Date()-new Date(f.created_at))/DAY_MS))} days</td><td>{fmt(f.due_date)}</td></tr>)}</tbody></table></div>:<div className="empty compactEmpty"><CheckCircle2/><h3>No pending findings.</h3></div>}</section></div></div>}
