 const visible=useMemo(()=>findings.filter(f=>(filter==='ALL'||f.status===filter||filter==='OVERDUE'&&overdue(f))&&(!search||f.title.toLowerCase().includes(search.toLowerCase())||f.description.toLowerCase().includes(search.toLowerCase()))),[findings,filter,search]);
