 function StoresPage(){return <main className="content"><div className="pageTitle"><div><span className="eyebrow">{stores.length} accessible stores</span><h1>Stores</h1><p>Choose a store to review its findings and progress.</p></div></div><div className="storeGrid">{stores.map(s=>{const fs=findings.filter(f=>f.store_id===s.id&&f.status!=='CLOSED');return <button className="storeCard" key={s.id} onClick={()=>{setStoreContext(s.id);setPage('findings')}}><div className="storeIcon"><Store/></div><div><span className="eyebrow">{s.store_code} · {s.area}</span><h2>{s.store_name}</h2><p>{fs.length} active · {fs.filter(overdue).length} overdue</p></div><ChevronRight/></button>})}</div></main>}
