  const sorted=[...performance].sort((a,b)=>{if(a.eligible!==b.eligible)return a.eligible?-1:1;let av=a[sort.key],bv=b[sort.key];if(typeof av==='string')return(sort.dir==='asc'?1:-1)*av.localeCompare(bv);av=av===null?(sort.dir==='asc'?Infinity:-Infinity):av;bv=bv===null?(sort.dir==='asc'?Infinity:-Infinity):bv;return(sort.dir==='asc'?1:-1)*(av-bv)});
  const setSorting=key=>setSort(x=>({key,dir:x.key===key&&x.dir==='desc'?'asc':'desc'})),arrow=key=>sort.key===key?(sort.dir==='desc'?' ↓':' ↑'):'';
  const bestStore=resolutionLeaders[0],best=bestStore?{...bestStore,score:Math.round(bestStore.resolutionRate)}:undefined,highestRate=resolutionLeaders[0],fastest=[...eligible].filter(x=>x.avgResolution!==null).sort((a,b)=>a.avgResolution-b.avgResolution)[0];
  const risk=x=>x.overdue*20+x.critical*25+x.pending*5+(x.avgPendingAge||0),attention=performance.filter(x=>x.total&&(x.score<70||x.overdue>=3||(x.avgPendingAge||0)>=7||x.critical>0)).sort((a,b)=>risk(b)-risk(a)),needsAttention=attention[0]||[...performance].filter(x=>x.total).sort((a,b)=>(a.score??101)-(b.score??101))[0];
  const byCat=cats.map(c=>({name:c.name,n:cohort.filter(f=>f.category_id===c.id).length})).filter(x=>x.n).sort((a,b)=>b.n-a.n),max=Math.max(1,...byCat.map(x=>x.n)),active=cohort.filter(f=>f.status!=='CLOSED'),ages=active.map(f=>Math.max(0,(now-new Date(f.created_at))/DAY_MS)),aging=[ages.filter(x=>x<=3).length,ages.filter(x=>x>3&&x<=7).length,ages.filter(x=>x>7&&x<=14).length,ages.filter(x=>x>14).length],overallAvg=calculateAverageResolutionDays(cohort),closed=cohort.filter(f=>f.status==='CLOSED').length,late=cohort.filter(f=>f.status!=='CLOSED'&&f.due_date&&new Date(f.due_date+'T23:59:59')<now).length;
