const SQL = String.raw`-- Store Notes Ver.2.0 Supabase setup (run once in SQL Editor)
create extension if not exists pgcrypto;
create type public.app_role as enum ('regional_manager','area_manager','store_manager');
create type public.finding_priority as enum ('LOW','MEDIUM','HIGH','CRITICAL');
create type public.finding_status as enum ('OPEN','IN_PROGRESS','FOR_VERIFICATION','CLOSED');
create type public.photo_kind as enum ('BEFORE','PROGRESS','AFTER');

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,email text not null,role app_role not null default 'store_manager',avatar_url text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.stores(id uuid primary key default gen_random_uuid(),store_code text not null unique,store_name text not null,area text,district text,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.user_store_access(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,store_id uuid not null references public.stores(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,store_id));
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,description text,is_active boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now());
create sequence public.finding_number_seq;
create table public.findings(id uuid primary key default gen_random_uuid(),finding_no text not null unique default ('SN-'||extract(year from now())::int||'-'||lpad(nextval('public.finding_number_seq')::text,6,'0')),store_id uuid not null references public.stores(id),created_by uuid not null references public.profiles(id),title text not null check(length(title) between 1 and 120),description text not null,category_id uuid references public.categories(id),priority finding_priority not null default 'MEDIUM',status finding_status not null default 'OPEN',assigned_to uuid references public.profiles(id),due_date date,date_observed date not null default current_date,closed_at timestamptz,closed_by uuid references public.profiles(id),verified_at timestamptz,verified_by uuid references public.profiles(id),is_archived boolean not null default false,archived_at timestamptz,archived_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.finding_photos(id uuid primary key default gen_random_uuid(),finding_id uuid not null references public.findings(id) on delete cascade,uploaded_by uuid not null references public.profiles(id),storage_path text not null unique,photo_type photo_kind not null,caption text,file_size bigint check(file_size>=0),created_at timestamptz not null default now());
create table public.finding_comments(id uuid primary key default gen_random_uuid(),finding_id uuid not null references public.findings(id) on delete cascade,user_id uuid not null references public.profiles(id),comment text not null check(length(comment) between 1 and 4000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.finding_activity(id uuid primary key default gen_random_uuid(),finding_id uuid not null references public.findings(id) on delete cascade,user_id uuid references public.profiles(id),activity_type text not null,old_value text,new_value text,description text,created_at timestamptz not null default now());

create index findings_store_idx on public.findings(store_id); create index findings_status_idx on public.findings(status); create index findings_priority_idx on public.findings(priority); create index findings_category_idx on public.findings(category_id); create index findings_created_idx on public.findings(created_at desc); create index findings_due_idx on public.findings(due_date); create index findings_assigned_idx on public.findings(assigned_to); create index findings_creator_idx on public.findings(created_by); create index findings_store_status_idx on public.findings(store_id,status,created_at desc); create index photos_finding_idx on public.finding_photos(finding_id); create index comments_finding_idx on public.finding_comments(finding_id,created_at);

create or replace function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_at(); create trigger findings_touch before update on public.findings for each row execute function public.touch_updated_at(); create trigger comments_touch before update on public.finding_comments for each row execute function public.touch_updated_at();
create or replace function public.my_role() returns app_role language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid() and is_active$$;
create or replace function public.can_access_store(s uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles p where p.id=auth.uid() and p.is_active and (p.role='regional_manager' or exists(select 1 from user_store_access a where a.user_id=p.id and a.store_id=s)))$$;
create or replace function public.protect_finding_update() returns trigger language plpgsql security definer set search_path=public as $$begin
 if public.my_role()='store_manager' then
  if new.store_id<>old.store_id or new.created_by<>old.created_by or new.priority<>old.priority or new.category_id is distinct from old.category_id or new.assigned_to is distinct from old.assigned_to or new.due_date is distinct from old.due_date or new.is_archived<>old.is_archived then raise exception 'Store Managers cannot change protected finding fields'; end if;
  if new.status='CLOSED' or not ((old.status='OPEN' and new.status in ('OPEN','IN_PROGRESS')) or (old.status='IN_PROGRESS' and new.status in ('IN_PROGRESS','FOR_VERIFICATION')) or old.status=new.status) then raise exception 'Status transition not permitted'; end if;
 end if;
 if new.status='CLOSED' and public.my_role() not in ('regional_manager','area_manager') then raise exception 'Only Area or Regional Managers can close'; end if;
 if new.is_archived and public.my_role()<>'regional_manager' then raise exception 'Only Regional Managers can archive'; end if; return new;end$$;
create trigger finding_update_guard before update on public.findings for each row execute function public.protect_finding_update();
create or replace function public.log_finding_activity() returns trigger language plpgsql security definer set search_path=public as $$begin
 if tg_op='INSERT' then insert into finding_activity(finding_id,user_id,activity_type,description) values(new.id,auth.uid(),'FINDING_CREATED','Finding created');return new;end if;
 if new.status<>old.status then insert into finding_activity(finding_id,user_id,activity_type,old_value,new_value,description) values(new.id,auth.uid(),case when new.status='CLOSED' then 'CLOSED' when old.status='CLOSED' then 'REOPENED' else 'STATUS_CHANGED' end,old.status::text,new.status::text,'Status changed from '||old.status||' to '||new.status);end if; return new;end$$;
create trigger finding_activity_log after insert or update on public.findings for each row execute function public.log_finding_activity();
create or replace function public.log_comment() returns trigger language plpgsql security definer set search_path=public as $$begin insert into finding_activity(finding_id,user_id,activity_type,description) values(new.finding_id,new.user_id,'COMMENT_ADDED',new.comment);return new;end$$;
create trigger comment_activity after insert on public.finding_comments for each row execute function public.log_comment();

alter table public.profiles enable row level security; alter table public.stores enable row level security; alter table public.user_store_access enable row level security; alter table public.categories enable row level security; alter table public.findings enable row level security; alter table public.finding_photos enable row level security; alter table public.finding_comments enable row level security; alter table public.finding_activity enable row level security;
create policy profiles_read on public.profiles for select to authenticated using (id=auth.uid() or public.my_role() in ('regional_manager','area_manager'));
create policy profiles_admin on public.profiles for update to authenticated using(public.my_role()='regional_manager') with check(public.my_role()='regional_manager');
create policy stores_read on public.stores for select to authenticated using(public.can_access_store(id)); create policy stores_admin on public.stores for all to authenticated using(public.my_role()='regional_manager') with check(public.my_role()='regional_manager');
create policy access_read on public.user_store_access for select to authenticated using(user_id=auth.uid() or public.my_role()='regional_manager'); create policy access_admin on public.user_store_access for all to authenticated using(public.my_role()='regional_manager') with check(public.my_role()='regional_manager');
create policy categories_read on public.categories for select to authenticated using(true); create policy categories_admin on public.categories for all to authenticated using(public.my_role()='regional_manager') with check(public.my_role()='regional_manager');
create policy findings_read on public.findings for select to authenticated using(public.can_access_store(store_id)); create policy findings_insert on public.findings for insert to authenticated with check(created_by=auth.uid() and public.can_access_store(store_id)); create policy findings_update on public.findings for update to authenticated using(public.can_access_store(store_id)) with check(public.can_access_store(store_id));
create policy photos_read on public.finding_photos for select to authenticated using(exists(select 1 from findings f where f.id=finding_id and public.can_access_store(f.store_id))); create policy photos_insert on public.finding_photos for insert to authenticated with check(uploaded_by=auth.uid() and exists(select 1 from findings f where f.id=finding_id and public.can_access_store(f.store_id)));
create policy comments_read on public.finding_comments for select to authenticated using(exists(select 1 from findings f where f.id=finding_id and public.can_access_store(f.store_id))); create policy comments_insert on public.finding_comments for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from findings f where f.id=finding_id and public.can_access_store(f.store_id)));
create policy activity_read on public.finding_activity for select to authenticated using(exists(select 1 from findings f where f.id=finding_id and public.can_access_store(f.store_id)));

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('store-findings','store-findings',false,2097152,array['image/jpeg','image/webp','image/png']) on conflict(id) do update set public=false,file_size_limit=2097152;
create policy storage_read on storage.objects for select to authenticated using(bucket_id='store-findings' and public.can_access_store((storage.foldername(name))[1]::uuid)); create policy storage_insert on storage.objects for insert to authenticated with check(bucket_id='store-findings' and public.can_access_store((storage.foldername(name))[1]::uuid));

insert into public.categories(name,sort_order) select x,row_number() over() from unnest(array['Store Standard','Fresh','Merchandising','Signages','Price Tags','Housekeeping','Equipment','Facilities','Safety','Inventory','Customer Service','Manpower','Promotions','Others']) x on conflict(name) do nothing;
insert into public.stores(store_code,store_name,area,district) values ('MON','Monumento','North Metro','District 1'),('MAY','Maypajo','North Metro','District 1'),('BBA','Bagong Barrio','North Metro','District 1'),('NAV','Navotas','North Metro','District 1'),('MAL','Malabon','North Metro','District 1'),('DEP','Deparo','North Caloocan','District 2'),('ZAB','Zabarte','North Caloocan','District 2'),('BSI','Bagong Silang','North Caloocan','District 2'),('CAM','Camarin','North Caloocan','District 2'),('PDB','Paso de Blas','North Caloocan','District 2') on conflict(store_code) do nothing;

-- After creating the first Auth user in Supabase, replace values and run:
-- insert into public.profiles(id,full_name,email,role) values('AUTH-USER-UUID','Your Name','you@company.com','regional_manager');
-- Regional Managers require no user_store_access rows. Assign Area/Store Managers explicitly.
`;

const README = `# Store Notes Ver.2.0 — setup and deployment\n\nStore Notes Ver.2.0 is a mobile-first React PWA that talks directly to Supabase. No server or service-role key is used in the browser.\n\n## 1. Supabase\n1. Create a free project at supabase.com and wait for it to finish.\n2. Open SQL Editor, download /setup.sql from the running app (or run npm run setup:sql), paste it, and click Run. This creates tables, indexes, triggers, strict RLS, private photo storage, categories, and sample stores.\n3. In Authentication > Providers, keep Email enabled. In Authentication > Users, create your first user.\n4. Copy that user's UUID. In SQL Editor run the final commented profiles insert from setup.sql, replacing UUID/name/email. Use regional_manager for the first account.\n5. In Project Settings > API, copy Project URL and the publishable/anon key. Never use the service_role key.\n\n## 2. Local configuration\nSet VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in your shell or hosting dashboard. Then run npm install and npm run dev. Without these values the app shows a configuration-required screen and does not load sample users.\n\n## 3. Users and store access\nCreate Auth users in the Supabase dashboard or a separately trusted admin process. Insert a matching profiles row. Assign Area and Store Managers by inserting user_store_access rows. Regional Managers automatically access every store. Browser-side account creation is intentionally omitted because it would require privileged credentials.\n\n## 4. Add the remaining 21 stores\nInsert rows into public.stores with a unique store_code, store_name, area, and district. The sample INSERT near the end of setup.sql is an easy template.\n\n## 5. Production build\nRun npm run build. The static site is written to dist/. Deploy that folder to Vercel, Netlify, GitHub Pages, or another static host. Configure both VITE_ variables before the build. No Node server is needed in production.\n\nNetlify: build command npm run build; publish directory dist. Vercel: framework preset Other; build command npm run build; output directory dist.\n\n## 6. Android installation\nOpen the deployed HTTPS URL in Chrome, sign in, open the browser menu, and choose Install app. The service worker caches the app shell; typed finding drafts are preserved locally when offline. Submissions require connectivity and can be retried.\n\n## Security notes\nRLS is the authorization boundary, not frontend filtering. Store Manager status transitions and protected fields are guarded by a database trigger. The photo bucket is private and limited to authenticated store access. Activity history has no user insert/update/delete policy and is written only by security-definer triggers.\n`;

